from .classes import CLASS_TYPES


def expected_stat(ingame_class: str, stat_name: str, rank: int) -> float:
	"""
	Returns the average value of a stat for a given class and rank.
	"""

	if ingame_class in CLASS_TYPES["Unranked"]:
		ingame_class = "Rookie"

	ingame_class = ingame_class.title()
	stat_name = stat_name.lower()

	stats = EXPECTED_STATS[ingame_class][stat_name]

	if isinstance(stats, list):
		idx = max(0, min(rank - 1, len(stats) - 1))
		return stats[idx]
	else:
		return stats
	
